const $=id=>document.getElementById(id);let lang=new URL(location.href).searchParams.get('lang')==='pt'?'pt':'en';
function render(){document.documentElement.lang=lang==='pt'?'pt-BR':'en';document.title=lang==='pt'?'ARES — Teste de compreensão':'ARES — Comprehension Test';document.querySelectorAll('[data-copy]').forEach(el=>el.textContent=copy[lang][el.dataset.copy]);$('test-language').value=lang;$('back-link').href='./?lang='+lang;$('open-app').href='./?lang='+lang;for(let i=1;i<=3;i++){const el=$('outcome-'+i),current=el.value;el.replaceChildren();for(const [value,key]of [['','empty'],['independent','independent'],['help','help'],['missed','missed']]){const o=document.createElement('option');o.value=value;o.textContent=copy[lang][key];el.append(o);}el.value=current;}gate();}
function gate(){$('export-observations').disabled=!$('observed-confirmation').checked||[1,2,3].some(i=>!$('outcome-'+i).value);}
$('test-language').addEventListener('change',()=>{lang=$('test-language').value==='pt'?'pt':'en';render();});$('test-form').addEventListener('change',gate);$('print-protocol').addEventListener('click',()=>window.print());
$('test-form').addEventListener('submit',e=>{e.preventDefault();gate();if($('export-observations').disabled)return;const data={schemaVersion:1,recordType:'facilitator-entered-comprehension-observations',recordedAt:new Date().toISOString(),language:lang,participantCode:$('participant-code').value.trim(),actualPersonDeclaredByFacilitator:true,independentlyVerified:false,projectValidationClaimsUpdated:false,tasks:[1,2,3].map(i=>({id:i,outcome:$('outcome-'+i).value,notes:$('notes-'+i).value.trim()})),followUp:{observedIssue:$('review-issue').value.trim(),proposedChangeAndRetest:$('review-change').value.trim()},referenceAssumptions:{autonomyMinutes:240,speedKmh:2.5,workMinutes:30,slopeLimitDegrees:12,reserveMinutesInitial:45,reserveMinutesTask2:50},limits:'Manual observations for a small comprehension test. Not a safety study, representative sample, or independently verified research result.'};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='ares-comprehension-observations.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('export-status').textContent=copy[lang].saved;});
render();
